import torch
from torch.utils.cpp_extension import load_inline

# CUDA kernel implementation
cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void rms_norm_kernel(
    const half* __restrict__ input,
    half* __restrict__ output,
    const float eps,
    const int batch_size,
    const int features,
    const int dim1,
    const int dim2
) {
    const int batch_idx = blockIdx.x;
    const int feature_idx = blockIdx.y;

    if (batch_idx >= batch_size || feature_idx >= features) return;

    // Shared memory for reduction
    extern __shared__ float sdata[];

    const int tid = threadIdx.x;
    const int total_elements = dim1 * dim2;

    // Each thread computes partial sum for its elements
    float sum = 0.0f;
    const int stride = blockDim.x;

    for (int i = tid; i < total_elements; i += stride) {
        const int idx = batch_idx * (features * dim1 * dim2) + feature_idx * (dim1 * dim2) + i;
        const float val = __half2float(input[idx]);
        sum += val * val;
    }

    sdata[tid] = sum;
    __syncthreads();

    // Reduction in shared memory
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    // Compute RMS for this feature
    const float rms = sqrtf(sdata[0] / total_elements + eps);

    // Normalize and write output
    for (int i = tid; i < total_elements; i += stride) {
        const int idx = batch_idx * (features * dim1 * dim2) + feature_idx * (dim1 * dim2) + i;
        output[idx] = __float2half(__half2float(input[idx]) / rms);
    }
}

// Optimized version using warp-level primitives
__global__ void rms_norm_kernel_optimized(
    const half* __restrict__ input,
    half* __restrict__ output,
    const float eps,
    const int batch_size,
    const int features,
    const int dim1,
    const int dim2
) {
    const int batch_idx = blockIdx.x;
    const int feature_idx = blockIdx.y;

    if (batch_idx >= batch_size || feature_idx >= features) return;

    const int total_elements = dim1 * dim2;
    const int elements_per_block = 128;
    const int num_blocks = (total_elements + elements_per_block - 1) / elements_per_block;

    float sum = 0.0f;

    // Process all elements for this feature
    for (int i = 0; i < total_elements; i++) {
        const int idx = batch_idx * (features * dim1 * dim2) + feature_idx * (dim1 * dim2) + i;
        const float val = __half2float(input[idx]);
        sum += val * val;
    }

    const float rms = sqrtf(sum / total_elements + eps);

    // Normalize and write output
    for (int i = 0; i < total_elements; i++) {
        const int idx = batch_idx * (features * dim1 * dim2) + feature_idx * (dim1 * dim2) + i;
        output[idx] = __float2half(__half2float(input[idx]) / rms);
    }
}
"""

